		assertFalse(holder.isInterface());
		assertSame(Object.class, holder.getSuperclass());
		assertFalse(CloseableIteration.class.isAssignableFrom(holder));
		Field field = holder.getDeclaredField("EMPTY_STATEMENT_ITERATION");
		assertSame(EmptyIteration.class, field.getType());
		Object empty = field.get(null);
		assertSame(EmptyIteration.class, empty.getClass());
